#!/usr/bin/env python3
"""Regenerates the pre-resolved descriptions (data/locale/autogenerated/...) when a mod
changes values in types.bin.

Files in data/locale/gui/<lang>/ contain templates such as
    "Base power: {fireball_projectile_spell_component/BasePower/float}"
and the ones in data/locale/autogenerated/gui/<lang>/ hold the same text already
resolved by Frozenbyte ("Base power: 50"). The game displays the autogenerated version.

Strategy: the template is used as a mould to locate, in the resolved text, the part
produced by each {...}. Only parts whose values changed between the original and the
modified types.bin are recomputed, copying the scale and decimals of the original.
"""
import math
import re

from luachunk import Chunk

PLACEHOLDER = re.compile(r'\{([^{}]*)\}')


def snake(name):
    out = []
    for i, c in enumerate(name):
        if c.isupper() and i > 0 and not name[i - 1].isdigit() and name[i - 1] != '_':
            out.append('_')
        out.append(c.lower())
    return ''.join(out)


class Resolver:
    """Maps a template key (object name in snake_case, sometimes truncated) to an object."""

    def __init__(self, db):
        self.db = db
        self.by_key = {}
        for s in db.object_names():
            self.by_key.setdefault(snake(s), []).append(s)
        self._cache = {}

    def candidates(self, key):
        if key not in self._cache:
            c = list(self.by_key.get(key, []))
            if not c:  # truncated key: accept objects whose name starts with it
                for k, names in self.by_key.items():
                    if k.startswith(key):
                        c += names
            self._cache[key] = c
        return self._cache[key]

    def value(self, key, prop, unit):
        last = None
        for name in self.candidates(key):
            try:
                v = self.db.get(name, prop)
            except KeyError as ex:
                last = ex
                continue
            if isinstance(v, (int, float)):
                return float(v)
        raise KeyError(last or f'unknown key {key}')


# --- placeholder expression evaluation ---------------------------------------------

def split_args(s):
    depth, cur, out = 0, '', []
    for c in s:
        if c == ',' and depth == 0:
            out.append(cur.strip())
            cur = ''
            continue
        depth += c == '('
        depth -= c == ')'
        cur += c
    if cur.strip():
        out.append(cur.strip())
    return out


def refs_in(expr):
    return re.findall(r'([a-z0-9_]+)/([A-Za-z0-9_]+)', expr)


def evaluate(expr, res):
    expr = expr.strip()
    m = re.fullmatch(r'(\w+)\((.*)\)', expr, re.S)
    if m and '/' not in m.group(1):
        args = [evaluate(a, res) for a in split_args(m.group(2))]
        fn = m.group(1)
        if fn == 'mul':
            return math.prod(args)
        if fn == 'add':
            return sum(args)
        if fn == 'sub':
            return args[0] - args[1]
        if fn == 'div':
            return args[0] / args[1]
        raise ValueError(f'unknown function {fn}')
    try:
        return float(expr)
    except ValueError:
        pass
    body = expr.split(':', 1)[0]
    parts = body.split('/')
    if len(parts) < 2:
        raise ValueError(f'unrecognised expression: {expr}')
    return res.value(parts[0], parts[1], parts[2] if len(parts) > 2 else None)


def render_like(old_text, old_val, new_val, fmt_spec):
    """Formats new_val the same way old_val was written in old_text."""
    t = old_text.strip()
    try:
        shown = float(t)
    except ValueError:
        return None
    scale = 1.0
    if old_val != 0:
        ratio = shown / old_val
        for k in range(-3, 3):
            if math.isclose(abs(ratio), 10.0 ** k, rel_tol=0.02):
                # the text may show the value as % and/or without sign (e.g. -0.05 -> "5")
                scale = math.copysign(10.0 ** k, ratio)
                break
        else:
            return None
    elif shown != 0:
        return None
    v = new_val * scale
    if fmt_spec:
        try:
            return format(v, fmt_spec)
        except ValueError:
            pass
    # The original generator writes %g-like with up to 2 decimals: 50, 3.5, 1.5
    return f'{v:.2f}'.rstrip('0').rstrip('.')


def regen_text(template, ready, res_old, res_new, log, key):
    parts = PLACEHOLDER.split(template)   # literal, expr, literal, expr, ...
    if len(parts) == 1:
        return None
    pattern = ''.join(re.escape(p) if i % 2 == 0 else '(.*?)' for i, p in enumerate(parts))
    m = re.fullmatch(pattern, ready, re.S)
    if not m:
        log.append(f'  ! {key}: resolved text does not match the template, skipped')
        return None
    caps = list(m.groups())
    changed = False
    for gi, expr in enumerate(parts[1::2]):
        if not refs_in(expr):
            continue  # {0}, {bind:...} etc. are resolved at runtime
        try:
            old_v, new_v = evaluate(expr, res_old), evaluate(expr, res_new)
        except (KeyError, ValueError):
            continue
        if math.isclose(old_v, new_v, rel_tol=1e-9, abs_tol=1e-12):
            continue
        fm = re.search(r':([^:/()]+)\s*$', expr)
        new_txt = render_like(caps[gi], old_v, new_v, fm.group(1) if fm else None)
        if new_txt is None:
            log.append(f'  ! {key}: could not reproduce the format of "{caps[gi]}" ({{{expr}}})')
            continue
        log.append(f'  {key}: {{{expr}}} "{caps[gi]}" -> "{new_txt}"')
        caps[gi] = new_txt
        changed = True
    if not changed:
        return None
    out = []
    for i, p in enumerate(parts):
        out.append(p if i % 2 == 0 else caps[i // 2])
    return ''.join(out)


def regen_file(template_bytes, ready_bytes, res_old, res_new, log):
    """Returns the new bytes of the autogenerated file, or None if nothing changed."""
    tpl = Chunk(template_bytes)
    rdy = Chunk(ready_bytes)
    tg, rg = tpl.globals_table(), rdy.globals_table()
    uses = {}
    for k, idx in rg.items():
        uses.setdefault(idx, []).append(k)
    changed = False
    for key, ridx in rg.items():
        if key not in tg:
            continue
        t = tpl.main.constants[tg[key]][1]
        r = rdy.main.constants[ridx][1]
        if t is None or r is None or b'{' not in t:
            continue
        new = regen_text(t.decode('utf-8'), r.decode('utf-8'), res_old, res_new, log, key)
        if new is None:
            continue
        if len(uses[ridx]) > 1:
            log.append(f'  ! {key}: text shared with {uses[ridx]}; all of them get the new text')
        rdy.main.constants[ridx] = (4, new.encode('utf-8'))
        changed = True
    return rdy.dump() if changed else None


def regen_all(script_pkg, db_old, db_new, overrides=None, log=None):
    """Regenerates every autogenerated file affected by the changes db_old -> db_new.

    overrides: {name: bytes} of locale files already changed by the mod (used instead of
    the originals). Returns {name: bytes} with only the autogenerated files that changed.
    """
    overrides = overrides or {}
    log = log if log is not None else []
    res_old, res_new = Resolver(db_old), Resolver(db_new)

    def get(name):
        if name in overrides:
            return overrides[name]
        e = script_pkg.find(name)
        return script_pkg.read(e) if e else None

    out = {}
    for e in script_pkg.entries:
        n = e.name
        if not (n.startswith('data/locale/gui/') and n.endswith('.lub')):
            continue
        auto = n.replace('data/locale/', 'data/locale/autogenerated/', 1)
        ready = get(auto)
        if ready is None:
            continue
        new = regen_file(get(n), ready, res_old, res_new, log)
        if new is not None:
            out[auto] = new
    return out
